"""Column helpers shared by every model module (docs/PLAN.md §9: uuidv7 keys, timestamptz)."""

from __future__ import annotations

import uuid
from datetime import datetime
from enum import StrEnum
from typing import Annotated, Any

from sqlalchemy import DateTime, Enum, Float, ForeignKey, text
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import mapped_column

from devgrill.infra.db import APP_SCHEMA

#: Primary key generated by Postgres 18 (time-ordered, index friendly).
UuidPk = Annotated[uuid.UUID, mapped_column(primary_key=True, server_default=text("uuidv7()"))]
CreatedAt = Annotated[
    datetime, mapped_column(DateTime(timezone=True), server_default=text("now()"))
]
UpdatedAt = Annotated[
    datetime,
    mapped_column(DateTime(timezone=True), server_default=text("now()"), onupdate=text("now()")),
]
Timestamp = Annotated[datetime, mapped_column(DateTime(timezone=True))]
JsonObject = Annotated[dict[str, Any], mapped_column(JSONB, server_default=text("'{}'::jsonb"))]

# Glicko-2 defaults (devgrill.domain.glicko2): rating 1500, deviation 350, volatility 0.06.
GlickoRating = Annotated[float, mapped_column(Float, server_default=text("1500"))]
GlickoRd = Annotated[float, mapped_column(Float, server_default=text("350"))]
GlickoVol = Annotated[float, mapped_column(Float, server_default=text("0.06"))]


def pg_enum[E: StrEnum](enum_cls: type[E], name: str) -> Enum:
    """A native Postgres enum in the app schema that stores the members' string values."""
    return Enum(
        enum_cls,
        name=name,
        schema=APP_SCHEMA,
        values_callable=lambda members: [m.value for m in members],
        validate_strings=True,
    )


def fk(target: str, *, ondelete: str = "CASCADE", use_alter: bool = False) -> ForeignKey:
    """A foreign key into the app schema (`table.column`)."""
    return ForeignKey(f"{APP_SCHEMA}.{target}", ondelete=ondelete, use_alter=use_alter)


def user_fk(*, ondelete: str = "CASCADE") -> ForeignKey:
    """Users are referenced through their profile, so app data never depends on the auth schema."""
    return fk("profiles.user_id", ondelete=ondelete)
